:root {
  --card-bg: #fdf6e3;
  --card-border: #b89a6a;
  --header-bg: #3b5c6e;
  --header-text: #e8dfc8;
  --label-color: #7a6040;
  --value-color: #2c3e2d;
  --divider-color: #c9b48a;
  --footer-bg: #eee3c8;
  --stamp-color: #8b2b2b;
  --stamp-border: #8b2b2b;
}

.gauge-card {
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 4px;
  width: 380px;
  padding: 0;
  overflow: hidden;
}

.card-header {
  background-color: var(--header-bg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
}

.station-id {
  color: var(--header-text);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  opacity: 0.8;
}

.card-title {
  color: var(--header-text);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.05em;
  margin: 0;
  text-transform: uppercase;
}

.card-date {
  color: var(--header-text);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  opacity: 0.8;
}

.readings {
  display: flex;
  align-items: center;
  padding: 20px 12px;
  gap: 0;
}

.reading-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
  margin: 0;
  gap: 6px;
}

.reading-label {
  color: var(--label-color);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.reading-value {
  color: var(--value-color);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.divider {
  width: 1px;
  height: 48px;
  background-color: var(--divider-color);
}

.card-footer {
  background-color: var(--footer-bg);
  border-top: 1px solid var(--card-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 16px;
}

.observer {
  color: var(--label-color);
  font-size: 12px;
  font-weight: 500;
  font-style: italic;
}

.stamp {
  color: var(--stamp-color);
  border: 2px solid var(--stamp-border);
  border-radius: 2px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  padding: 2px 7px;
}
